const body = $input.first().json.body;
const isObject = body !== null && typeof body === 'object' && !Array.isArray(body);
const fields = ['request_id', 'query', 'type', 'access_levels', 'top_k'];
const received = {};
for (const field of fields) received[field] = isObject && Object.prototype.hasOwnProperty.call(body, field) ? body[field] : null;
return [{ json: { step: 'P1-2 STEP 1', mock: true, diagnostic_only: true, body_is_object: isObject, received } }];
